/**
 * Map file as the client reads it: the JSON format of docs/design/map-format.md.
 *
 * The map is data, not rules: the client only draws it. The server and `gow-maps validate`
 * check the files, so the client trusts the shape and does no validation of its own.
 *
 * TODO(#45): replace these hand-written types with the ones generated by PRO-02.
 */

/** Player id of a 1v1 match, or `null` for "no owner". */
export type PlayerId = 0 | 1;

export type Terrain = 'plains' | 'forest' | 'mountains';

export interface MapMetaJson {
  readonly name: string;
  readonly version: number;
  readonly symmetry: 'rot180';
  /** World size; coordinates are in `[0, width] × [0, height]`, y grows down. */
  readonly width: number;
  readonly height: number;
}

export interface MapNodeJson {
  /** Equals the index in `nodes`. */
  readonly id: number;
  readonly x: number;
  readonly y: number;
  readonly terrain: Terrain;
  readonly vp: number;
  readonly base_capacity: number;
  readonly capital_of: PlayerId | null;
  readonly start_owner: PlayerId | null;
  readonly start_units: number;
  readonly start_charged: number;
  readonly start_stock: number;
}

export interface MapEdgeJson {
  /** Equals the index in `edges`. */
  readonly id: number;
  readonly a: number;
  readonly b: number;
  readonly base_width: number;
  readonly max_width: number;
  readonly travel_ticks: number;
}

export interface MapJson {
  readonly meta: MapMetaJson;
  readonly nodes: readonly MapNodeJson[];
  readonly edges: readonly MapEdgeJson[];
  readonly mirror: {
    readonly nodes: Readonly<Record<string, number>>;
    readonly edges: Readonly<Record<string, number>>;
  };
}
